   722  static void read_text(PInfo pi) {
   723      char  buf[MAX_TEXT_LEN];
   724      char *b         = buf;
   725      char *alloc_buf = 0;
   726      char *end       = b + sizeof(buf) - 2;
   727      char  c;
   728      int   done = 0;
   729
   730      while (!done) {
   731          c = *pi->s++;
   732          switch (c) {
   733          case '<':
   734              done = 1;
   735              pi->s--;
   736              break;
   737          case '\0': set_error(&pi->err, "invalid format, document not terminated", pi->str, pi->s); return;
   738          default:
   739              if (end <= (b + (('&' == c) ? 7 : 0))) { /* extra 8 for special just in case it is sequence of bytes */
   740                  unsigned long size;
   741
   742                  if (0 == alloc_buf) {
   743                      size      = sizeof(buf) * 2;
   744                      alloc_buf = ALLOC_N(char, size);
   745                      memcpy(alloc_buf, buf, b - buf);
   746                      b = alloc_buf + (b - buf);
   747                  } else {
   748                      unsigned long pos = b - alloc_buf;
   749
   750                      size = (end - alloc_buf) * 2;
   751                      REALLOC_N(alloc_buf, char, size);
   752                      b = alloc_buf + pos;
   753                  }
   754                  end = alloc_buf + size - 2;
   755              }
   756              if ('&' == c) {
   757                  if (0 == (b = read_coded_chars(pi, b))) {
   758                      return;
   759                  }
   760              } else {
   430          default:
