   471              attr_stack_cleanup(&attrs);
   472              set_error(&pi->err, "invalid format, element not closed", pi->str, pi->s);
   473              return 0;
   474          }
   475          pi->s++; /* past > */
   476          pi->pcb->add_element(pi, ename, attrs.head, hasChildren);
   477          pi->pcb->end_element(pi, ename);
   478
   479          attr_stack_cleanup(&attrs);
   480          return 0;
   481      }
   482      /* read attribute names until the close (/ or >) is reached */
   483      while (!done) {
   484          if ('\0' == c) {
   485              if (pi->end <= pi->s) {
   486                  break;
   487              }
   488              next_non_white(pi);
   489              c = *pi->s;
   490          }
   491          pi->last = 0;
