   202                      read_comment(&pi);
   203                  }
   204              } else if ((TolerantEffort == options->effort) ? 0 == strncasecmp("DOCTYPE", pi.s, 7)
   205                                                             : 0 == strncmp("DOCTYPE", pi.s, 7)) {
   206                  pi.s += 7;
   207                  read_doctype(&pi);
   208              } else {
   209                  set_error(err, "invalid format, DOCTYPE or comment expected", pi.str, pi.s);
   210                  helper_stack_cleanup(&pi.helpers);
   211                  return Qnil;
   212              }
   213              break;
   214          case '\0':
